{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work. First, we compiled information from 18 studies in the last 20 years (between 2002 and 2022) that reviewed the quality of meta-analyses in ecology, evolution and related fields. These papers provided different insights on the compliance with different standards of reporting quality and with recommended execution steps that should be part of a meta-analysis. Second, we evaluated the recognition and treatment of non-independence for the ecological meta-analyses included in Pappalardo et al. [1], and extracted new data on quality criteria to compare it with the other reviews. Finally, we summarized the level of compliance for different quality criteria across these 18 previous meta-analysis reviews and the new data taken from papers reviewed in Pappalardo et al [1].",
      "reason": "The introduction explicitly states the review’s objectives in terms of specific tasks (reviewing literature quality, collecting new data, evaluating recognition/treatment of non-independence, and summarizing compliance across criteria)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work.",
      "reason": "The review is a meta-evaluation of the quality of ecological meta-analyses, not a review of intervention effects with planned intervention comparisons; therefore PICO-style planned comparisons are not applicable based on the provided evidence."
    }
  ],
  "confidence": 78
